// 自动生成的离线下载内容；与 guides/*.html 同源，支持直接从 file:// 打开原型。
const businessGuideDownloads = {"devices":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>设备列表技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#assembly\">2. 列表怎么组合</a><a href=\"#fields\">3. 卡片字段从哪里来</a><a href=\"#refresh\">4. 刷新和失败怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>设备列表技术说明</h1><p class=\"guide-lead\">本人设备按人员 / 宠物绑定聚合；直接分享给我的设备单独校验授权，并入设备列表展示。</p><p class=\"guide-scope\">地图顶部按人选择其关联设备，设备列表包含自有设备与直接 DEVICE 分享。档案分享及其继承设备已移出范围。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>获取照护对象</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects</code></span><small>完整刷新时 1 次</small></li><li><strong>获取人员绑定的设备</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/person/{personId}/device-bindings</code></span><small>每个人员 1 次</small></li><li><strong>获取宠物绑定的设备</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/pet/{petId}/device-bindings</code></span><small>每个宠物 1 次</small></li><li><strong>获取在线状态</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/state</code></span><small>每台设备 1 次</small></li><li><strong>获取电量、信号、位置和上报时间</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/realtime</code></span><small>每台设备 1 次</small></li><li><strong>发现已接受的直接设备授权</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/shares/received</code></span><small>仅合并当前接收人、未撤销且未到期的 DEVICE 记录</small></li></ol><div class=\"guide-notes\"><p>路径相对所选环境 API 根地址，包含 /api/admin 或 /admin 时不重复拼接。</p><p>公共业务客户端使用 Bearer Token、X-TimeZone 和 lang；专用认证与图片客户端按公共约定处理。</p></div></div></section><section class=\"guide-section\" id=\"assembly\"><h2><span class=\"guide-section-number\">2</span>列表怎么组合</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>筛对象</strong><p><code>userId == 当前用户</code>、<code>status == ACTIVE</code>、类型为 PERSON / PET。</p></li><li><strong>查绑定</strong><p>用对象数字 ID 查询；返回的 <code>bindType</code>、<code>bindToId</code> 必须与请求对象一致。</p></li><li><strong>合设备</strong><p>按 <code>deviceId</code> 去重、合并使用者，按设备 ID 字典序排列。</p></li><li><strong>补数据</strong><p>读取 state，再读取 realtime，组合后展示卡片。</p></li><li><strong>共享列表</strong><p>从已接受的 DEVICE 邀请按设备合并权限，只读取允许的数据；不沿用人员 / 宠物档案权限发现设备。</p></li></ol><p class=\"guide-example\">A 绑定 D1、D2，B 绑定 D1 → 显示 2 台设备；D1 的使用者是 A、B。</p><div class=\"guide-diagrams\"><figure><figcaption><strong>数据组合流程图</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"数据组合流程图\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"数据组合流程图\"></figure><figure><figcaption><strong>首次加载时序图</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"首次加载时序图\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"首次加载时序图\"></figure></div><div class=\"guide-notes\"><p>绑定记录的 <code>id</code> 不是 <code>deviceId</code>；<code>primaryDeviceId</code> 不能代替完整绑定列表。ID 使用无损字符串或 Int64，不经 Double 转换。</p><p>设备详情传 deviceId；使用者详情传对象类型和数字 ID。同名对象也要按对象 ID 区分。</p><p>首页地图顶部按人筛选。共享设备在设备列表“全部”分类单独成组，不因展示在同一列表而获得自有设备的编辑权。</p></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>卡片字段从哪里来</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>设备名称、编号</td><td>统一命名规则与 deviceId</td><td>Prod 尚未接入正式昵称来源，使用编号尾号；Mock 可提供演示名称，不用产品名或他人资料自动补名。</td></tr><tr><td>在线状态</td><td>state.value</td><td>online 在线；offline 离线；notactive 未激活；其他未知。</td></tr><tr><td>电量</td><td>generalData.battery</td><td>0–100 显示百分比；0% 有效。</td></tr><tr><td>定位方式</td><td>generalData.isGPS</td><td>true 显示 GPS；其他情况不自行推断 WiFi / LBS。</td></tr><tr><td>信号</td><td>generalData.signalSize</td><td>显示原始值，不自行换算强 / 中 / 弱。</td></tr><tr><td>位置</td><td>latestLocation.lat / lng / locStatus</td><td>有效坐标显示“位置已上报”；当前不显示地址。</td></tr><tr><td>上报时间</td><td>latestLocation.dateTime / generalData.dateTime</td><td>离线取较晚的最后上报时间；位置展示须通过同次上报校验，不把 App 刷新时间冒充设备上报时间。</td></tr><tr><td>使用者</td><td>关联对象的 displayName</td><td>保留每个关联对象及其详情入口。家人 / 宠物分类按对象类型判断。</td></tr><tr><td>在线设备数</td><td>当前分类内的设备状态</td><td>显示在线数 / 总数；有未知状态或关系未确认时显示 —。</td></tr><tr><td>待处理提醒</td><td>当前列表未接入计数</td><td>显示 —。</td></tr><tr><td>上报阶段</td><td>state + realtime</td><td>区分从未上报、上报过但当前离线、已有上报；已有上报仍须校验有效位置。尚未读到 realtime 为未知，不直接当作从未上报。</td></tr></tbody></table></div><div class=\"guide-notes\"><p><code>generalData</code>、<code>latestLocation</code> 均来自 realtime。电量、信号等没有读取结果时显示“未读取”；读取成功但字段缺失时显示“未上报”。</p></div></div></section><section class=\"guide-section\" id=\"refresh\"><h2><span class=\"guide-section-number\">4</span>刷新和失败怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>完整刷新</strong><p>重新查对象、绑定、state 和 realtime；绑定 / 解绑后也要更新关系。</p></li><li><strong>自动刷新</strong><p>前台更新已有设备的 state / realtime，每轮结束等待 15 秒；离页或进后台停止。各阶段最多并发 4 个任务，不重叠刷新。</p></li><li><strong>关系失败</strong><p>任一对象绑定读取失败、身份不符或同设备 productKey 冲突，整轮发现失败，不能展示为完整列表。</p></li><li><strong>状态失败</strong><p>保留设备，标记未知 / 未确认，不能直接当作离线。</p></li><li><strong>实时数据失败</strong><p>网络或 HTTP 408/429/5xx 可保留同账号旧读数并标记失败；鉴权、权限等不可保留错误不沿用旧遥测。</p></li><li><strong>暂无上报</strong><p>realtime 返回 <code>code=0、ok≠false、data=null</code> 时清除旧读数。</p></li><li><strong>连续失败与切账号</strong><p>连续 3 轮每台设备都至少有一项读取失败，暂停自动刷新，允许手动重试。账号、环境或请求版本变化后丢弃旧请求结果。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>共享设备列表</strong><p>直接 DEVICE 的 LOCATION-only 在 10-19 有真实双账号记录；其他 scopes / MANAGER、到期及未注册后注册场景仍待验。</p></li><li><strong>设备展示资料</strong><p>命名回退已统一；Prod 正式昵称来源、地址和用途仍待接入，产品缺失展示与长期刷新按各自验收边界处理。</p></li><li><strong>提醒数据</strong><p>待处理数量、最近告警和处理状态尚未接入当前列表，需确认来源。</p></li></ul><div class=\"guide-notes\"><p>原型中的昵称、地址、提醒数字是演示数据。本说明记录 Android 实现，不代表本轮完成后端业务验收。</p></div></div></section><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>RemoteAppDeviceReadRepository.kt / HomeScreen.kt / DeviceListScreen.kt / CloudSubjectFilter.kt / SharedDeviceReader.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","subjects":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>照护对象技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 业务流程怎么走</a><a href=\"#fields\">3. 字段怎么提交</a><a href=\"#failure\">4. 失败时怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>照护对象技术说明</h1><p class=\"guide-lead\">人员和宠物共用管理流程，按类型调用接口；保存后回读详情和列表再更新界面。</p><p class=\"guide-scope\">资料写入仅开放给本人名下 ACTIVE 的 PERSON / PET。本人账号资料是另一类资源。 不提供人员或宠物档案分享；头像和设备绑定仍各自按原规则处理。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>读取照护对象列表</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects</code></span><small>进入管理页及保存后刷新</small></li><li><strong>创建人员 / 宠物</strong><span class=\"guide-api-route\"><b>POST</b><code>/app/subjects/person</code></span><span class=\"guide-api-route\"><b>POST</b><code>/app/subjects/pet</code></span><small>只发送一次 POST</small></li><li><strong>读取对象详情</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/person/{personId}</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/pet/{petId}</code></span><small>进入详情、写入前后核对</small></li><li><strong>修改资料、头像或归档</strong><span class=\"guide-api-route\"><b>PATCH</b><code>/app/subjects/person/{personId}</code></span><span class=\"guide-api-route\"><b>PATCH</b><code>/app/subjects/pet/{petId}</code></span><small>按操作发送差量 PATCH</small></li><li><strong>读取关联设备</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/person/{personId}/device-bindings</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/pet/{petId}/device-bindings</code></span><small>详情展示及归档前检查</small></li><li><strong>检查分享关系</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/person/{personId}/shares</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/pet/{petId}/shares</code></span><small>当前用于归档前检查</small></li><li><strong>上传对象头像</strong><span class=\"guide-api-route\"><b>POST</b><code>/sys-file/upload</code></span><small>用户确认预览后上传</small></li></ol><div class=\"guide-notes\"><p>路径中的 personId / petId 是对象数字 ID。页面中的 PERSON:101 / PET:101 是带类型的标识，不能整个放进数值路径。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>业务流程怎么走</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>读取</strong><p>按人员 / 宠物筛选列表；点击对象后读取详情和关联设备，不用名称识别对象。</p></li><li><strong>新增</strong><p>校验表单，POST 一次；使用返回的对象 ID 查询详情，再查列表确认出现。</p></li><li><strong>编辑</strong><p>保存前重读详情，检查待改字段没有被其他入口修改；PATCH 差量后回读详情和列表。</p></li><li><strong>删除</strong><p>页面按钮称“删除”，实际 PATCH status=ARCHIVED。重新确认归属、状态及设备 / 历史分享关系后提交，再回查详情和列表。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>照护对象操作流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"照护对象操作流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"照护对象操作流程\"></figure><figure><figcaption><strong>编辑资料回读时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"编辑资料回读时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"编辑资料回读时序\"></figure></div><div class=\"guide-notes\"><p>删除后资料保留但退出当前列表，暂不支持恢复；不自动解绑、撤销服务器历史授权或回收头像。任何历史分享记录非空仍会阻止当前删除流程。</p></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>字段怎么提交</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>创建公共部分</td><td>type、displayName、profile</td><td>未填写项省略；名称必填，PERSON / PET 必须与入口一致。</td></tr><tr><td>身高与体重</td><td>创建：profile.heightCm / weightKg；编辑：height / weight</td><td>创建和 PATCH 不能直接复用同一个请求对象；宠物没有身高项。</td></tr><tr><td>人员资料</td><td>gender、birthDate、relationToOwner、healthMonitoringEnabled</td><td>创建放 profile；编辑放根层。生日为 YYYY-MM-DD，false 不能当作未填写。</td></tr><tr><td>宠物资料</td><td>species、breed、gender、birthDate、neutered、activityTargetMinutes</td><td>新增 species 必须选 DOG / CAT / OTHER；neutered 发送 1 / 0，数值 0 要保留。</td></tr><tr><td>对象头像</td><td>PATCH 顶层 avatarUrl</td><td>先上传再保存返回地址，移除发送空串；与本人账号的 avatar 字段不同。</td></tr></tbody></table></div><div class=\"guide-notes\"><p>普通资料目前不支持清空已有值，不能把 null、空串和省略当成同一种操作。头像移除是单独实现的例外。</p></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>失败时怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>写入结果未确认</strong><p>请求超时或回查不一致时先刷新核对，不自动重发 POST / PATCH，也不能按名称猜测创建成功。</p></li><li><strong>编辑冲突</strong><p>待改字段与编辑基线不一致时停止保存，刷新后重新编辑。</p></li><li><strong>关联未确认</strong><p>设备或分享关系读取失败时阻止归档，不能把读取失败当作空列表。</p></li><li><strong>头像失败</strong><p>上传和保存地址分别确认；上传成功但资料保存失败，不等于头像已更新，也不自动删除服务器文件。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>尚未开放</strong><p>普通资料清空、备注、创建时选图上传、归档对象列表及恢复。</p></li><li><strong>后端待确认</strong><p>PET species 文档差异、历史分享关系下的删除约束、上传文件可信回收。人员 / 宠物档案分享不再是待实现项。</p></li></ul><div class=\"guide-notes\"><p>对象头像沿用账号头像的图片校验与上传接口；新增 / 编辑 / 归档的既有验收范围见主仓库对应验证记录，本轮只整理说明。</p></div></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>RemoteSubjectRepository.kt / SubjectProfileValues.kt / RemoteSubjectAvatarEditor.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","bindings":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>蓝牙接入、设备绑定与解绑技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 业务流程怎么走</a><a href=\"#fields\">3. 参数怎么区分</a><a href=\"#failure\">4. 失败时怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>蓝牙接入、设备绑定与解绑技术说明</h1><p class=\"guide-lead\">蓝牙接入先连接读取完整 IMEI 和固件身份，再进入产品与使用者确认；云端绑定双视图回查一致后保存本地 BLE 关联。</p><p class=\"guide-scope\">绑定目标是本人名下 ACTIVE 的人员或宠物。解绑解除一条关联，不等于删除设备或转移所有权。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>选择使用者</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects</code></span><small>筛出本人 ACTIVE 人员 / 宠物</small></li><li><strong>核对使用者详情</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/person/{personId}</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/pet/{petId}</code></span><small>写入及回查前确认身份、归属、状态</small></li><li><strong>读取可选产品</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/products</code></span><small>按 productKey 选择，不能硬编码型号</small></li><li><strong>读取已有设备的产品</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/product</code></span><small>管理页先确认自有关系；不用于探测未绑定设备</small></li><li><strong>读取对象侧设备关联</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/person/{personId}/device-bindings</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/pet/{petId}/device-bindings</code></span><small>与通用查询对照</small></li><li><strong>读取通用绑定视图</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/bindings</code></span><small>query：bindType、bindToId</small></li><li><strong>绑定设备</strong><span class=\"guide-api-route\"><b>POST</b><code>/app/device/bind</code></span><small>一次 POST，随后回查</small></li><li><strong>解除关联</strong><span class=\"guide-api-route\"><b>DELETE</b><code>/app/device/bind/{id}</code></span><small>DELETE 路径传绑定记录 ID</small></li></ol><div class=\"guide-notes\"><p>扫描、GATT 连接和身份读取是本地 BLE 操作，不是 HTTP 绑定。BLE 广播名称或 MAC 尾号不能替代完整 IMEI。</p><p>绑定仍走 POST /app/device/bind，解绑按 bindingId 走 DELETE；不混用人员 / 宠物路径下的重复写入口。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>业务流程怎么走</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>连接读身份</strong><p>蓝牙入口仅接受支持的 EV04 / EV05 / EV07B 广播族；连接后读取固件版本、15 位 IMEI 和设备 MAC 回包，校验请求 SID、字段数量与长度。该步骤不保存参数。</p></li><li><strong>核对设备与产品</strong><p>完整 IMEI 作为云端 deviceId，连接地址仅用于 BLE；已绑定设备入口必须与预期 deviceId 一致，再核对当前账号已有关系及可选产品。</p></li><li><strong>选择使用者并绑定</strong><p>选择本人 ACTIVE 人员 / 宠物及产品。已有同一对象、产品关系时只确认；其他对象关系不自动改绑。提交一次 POST。</p></li><li><strong>双视图确认</strong><p>对象 device-bindings 与 /app/device/bindings 的记录、设备、产品和目标均一致才确认成功；蓝牙接入随后按账号和环境保存已核验的本地关联。</p></li><li><strong>解绑</strong><p>核对可信 bindingId 后 DELETE 一次，再查两个视图确认消失；解绑不等于删除设备、转移所有权或自动撤销所有授权。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>绑定与解绑流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"绑定与解绑流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"绑定与解绑流程\"></figure><figure><figcaption><strong>绑定后双视图回查时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"绑定后双视图回查时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"绑定后双视图回查时序\"></figure></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>参数怎么区分</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>deviceId</td><td>设备标识 String</td><td>当前校验为 1–128 位字母、数字、下划线或连字符；不要自行当作数值解析。</td></tr><tr><td>bindType</td><td>PERSON / PET</td><td>与选择的使用者类型保持一致。</td></tr><tr><td>bindToId</td><td>对象数字 ID（Long）</td><td>来自人员 / 宠物资料，不传 PERSON:101 这样的组合值。</td></tr><tr><td>productKey</td><td>可选产品返回值</td><td>与选中的产品一致，不把产品名称或型号当作 key。</td></tr><tr><td>bindingId</td><td>绑定记录的 id</td><td>由查询结果取得，专用于核对和解绑，不等于 deviceId。</td></tr><tr><td>BLE 身份</td><td>完整 IMEI、协议族、连接地址、固件版本</td><td>连接地址可能随机变化；不能用名称尾号绑定，不向云绑定体夹带无关 BLE 字段。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>失败时怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>服务端拒绝</strong><p>保留可理解的拒绝提示，不继续进入成功页面。</p></li><li><strong>写入后超时 / 断网</strong><p>不能认定服务器没执行；进入结果未确认状态，先重新查询绑定关系，不自动重放写入。</p></li><li><strong>两个视图不一致</strong><p>记录重复、数量或内容不一致都不能确认成功，不从部分结果推断关系。</p></li><li><strong>账号或环境变化</strong><p>终止当前确认流程，丢弃旧上下文结果；不要把前一账号的关联写入当前列表。</p></li><li><strong>身份或本地关联失败</strong><p>IMEI 不匹配即断开，不继续绑定；绑定已确认但本地关联保存失败时单独报错，先回查关系，不盲目再绑。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>仍需真机验证</strong><p>扫码入口、新版拒绝提示、断网后写入回查及真实硬件持续上报。</p></li><li><strong>后端待确认</strong><p>改绑 / 转移所有权、共享关系失效等规则。不能从解绑成功自动推定这些操作已完成。</p></li><li><strong>既有实机范围</strong><p>10-20 指定 EV07BA 完成真实解绑、失权、BLE 身份读取及新绑定回查。10-23 同设备新旧配置入口均出现 BLE_GATT_UNAVAILABLE，连接稳定性仍待复验；不外推其他型号已通过。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>BleOnboardingIdentityReader.kt / CloudDeviceLifecycleViewModels.kt / RemoteAppDeviceLifecycleRepository.kt / BleDeviceAssociationStore<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","overview":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>设备详情技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 页面怎么加载</a><a href=\"#fields\">3. 每个区域展示什么</a><a href=\"#refresh\">4. 刷新和失败怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>设备详情技术说明</h1><p class=\"guide-lead\">设备基础状态与健康告警分开读取；基础信息先显示，规则结果返回后再补 AI 内容。</p><p class=\"guide-scope\">Mock 与 Prod 共用 feature:device 的云详情结构；自有与直接分享设备分别校验关系和权限。健康 / 告警读取取决于当前环境及授权。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>在线状态、定位和遥测</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/state</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/realtime</code></span><small>复用设备列表发现及读取链路</small></li><li><strong>设备产品资料</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/product</code></span><small>确认关系后读取，可单独降级</small></li><li><strong>设备直接分享记录</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/shares</code></span><small>授权读取与邀请管理分别处理，管理流程见设备分享说明</small></li><li><strong>概览指标与摘要</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/evaigc/devices/{deviceId}/overview</code></span><small>先 includeSummary=false，再 true</small></li><li><strong>日 / 周 / 月健康数据</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/evaigc/devices/{deviceId}/health</code></span><small>首次进入或切换周期时读取</small></li><li><strong>近期告警列表</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/evaigc/devices/{deviceId}/alerts</code></span><small>进入设备后读取</small></li><li><strong>单条告警解释</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/evaigc/devices/{deviceId}/alerts/{alertId}/analysis</code></span><small>打开告警后先 includeAi=false，再 true</small></li></ol><div class=\"guide-notes\"><p>新增分析接口来自当前客户端声明，不在原 37 项 App Device / App Subject 快照中。原有 /events 与这组告警读取接口不是同一入口。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>页面怎么加载</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>确认设备</strong><p>以 deviceId 查当前对象关联；不能因为 state / realtime 能访问就认定拥有该设备。</p></li><li><strong>填充基础区域</strong><p>展示状态、遥测、使用者和产品；各区域独立保留加载、空数据和失败状态。</p></li><li><strong>读取分析</strong><p>读取概览和告警列表。概览先展示规则结果，再请求 AI；健康首次进入标签才读取。</p></li><li><strong>按交互补充</strong><p>切换健康周期重新读取；点告警后请求该 alertId 的规则解释及 AI，关闭时取消解释请求。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>设备详情分区加载流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"设备详情分区加载流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"设备详情分区加载流程\"></figure><figure><figcaption><strong>规则先显示再补 AI 时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"规则先显示再补 AI 时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"规则先显示再补 AI 时序\"></figure></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>每个区域展示什么</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>在线 / 电量 / 位置</td><td>state、realtime</td><td>沿用设备列表规则；状态未知不能显示离线，电量 0% 不能丢弃。</td></tr><tr><td>产品与使用者</td><td>product + 对象绑定</td><td>列表与详情共用命名规则，Prod 暂无正式昵称时用编号尾号；产品缺失 / 停用仅产品区降级，鉴权和未知拒绝仍清除受限数据。</td></tr><tr><td>概览与健康指标</td><td>metrics 的 value / unit / available</td><td>使用服务端单位与可用标记；没有值显示 —，不补零。</td></tr><tr><td>健康趋势</td><td>trend.points、period、date</td><td>日 / 周 / 月分别读取，保留当前周期；date 当前按 UTC 日期，小时桶按手机时区展示。</td></tr><tr><td>告警</td><td>alerts 的 alertId、timeMillis、risk</td><td>按实际返回展示；告警解释使用同一设备与 alertId，不等于推送或已读状态。</td></tr><tr><td>AI 摘要 / 解释</td><td>summary / analysis、risk</td><td>AI 返回后替换同一请求区域；失败保留已有规则结果，不编造分析。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"refresh\"><h2><span class=\"guide-section-number\">4</span>刷新和失败怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>基础数据</strong><p>前台每轮结束约 15 秒后刷新 state / realtime；离页或后台停止。更新不重建地图或强制复位视野。</p></li><li><strong>分析数据</strong><p>不跟随 15 秒轮询反复请求 AI。手动刷新重读概览、告警及已打开过的健康区域。</p></li><li><strong>环境未部署</strong><p>404 显示环境未提供；拒绝或返回无效时清除受限结果，不把缺数据解释成健康正常。</p></li><li><strong>读取慢或失败</strong><p>规则先显示，AI 独立等待；AI 失败不自动重试。普通网络失败可保留同设备上次结果并标记失败。</p></li><li><strong>切换设备 / 账号</strong><p>取消旧请求，并核对设备、账号和环境后才接收响应，避免旧结果覆盖新页面。</p></li><li><strong>语言切换</strong><p>按语言版本重新请求规则与 AI，同一设备保留已选健康周期；迟到的旧语言响应不覆盖新语言。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>环境差异</strong><p>10-21 在 81 有中英文概览及健康周期切换记录；健康样本和实际告警缺失时，不能确认统计准确性或真实告警解释。</p></li><li><strong>服务端问题</strong><p>健康分析时段、风险窗口口径及定位距离异常待处理；不能把当前 AI 输出视为已校准结论。</p></li><li><strong>尚未形成完整流程</strong><p>真实持续移动、告警处置与推送、轨迹和围栏仍未闭环。设备分享、统一配置、查找已有独立说明，分别按各自限定证据判断。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>feature:device/cloud/CloudDeviceDetailViewModel.kt / UnifiedCloudDeviceDetailScreen.kt / CloudDeviceInsightViewModel.kt / SharedDeviceReader.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","location":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>地图与立即定位技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 位置和指令怎么组合</a><a href=\"#fields\">3. 位置字段怎么用</a><a href=\"#refresh\">4. 刷新和失败怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>地图与立即定位技术说明</h1><p class=\"guide-lead\">地图显示设备最后一次有效上报；立即定位只发指令，新的位置仍从 realtime 获取。</p><p class=\"guide-scope\">首页地图顶部按人选择自有关联设备；详情展示单台最后有效位置。直接共享设备按 LOCATION 权限进入只读查看，不承诺持续追踪。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>发现当前使用者</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects</code></span><small>设备发现流程复用设备列表</small></li><li><strong>获取关联设备</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/person/{personId}/device-bindings</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/pet/{petId}/device-bindings</code></span><small>按 deviceId 合并后读取</small></li><li><strong>读取最后位置及时间</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/realtime</code></span><small>首页和设备地图更新位置的来源</small></li><li><strong>显示在线状态</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/state</code></span><small>在线状态与位置时间分别判断</small></li><li><strong>发送立即定位</strong><span class=\"guide-api-route\"><b>POST</b><code>/app/device/{deviceId}/function</code></span><small>query：functionId=singleLocating；JSON body：{}</small></li></ol><div class=\"guide-notes\"><p>立即定位入口在云设备详情地图中；首页不自动向全部设备发送指令。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>位置和指令怎么组合</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>发现设备</strong><p>复用对象 → 绑定 → deviceId 的链路，确认单台详情的设备关系。</p></li><li><strong>判断位置</strong><p>校验 latestLocation 坐标、定位状态及同次上报时间；未取得有效位置时显示空态。</p></li><li><strong>绘制地图</strong><p>原始坐标按当前地图服务转换一次，标记、相机和覆盖物采用一致坐标系。</p></li><li><strong>立即定位</strong><p>确认自有关系，POST 一次；受理后提示已发起请求，继续通过实时数据读取设备实际回传。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>位置读取与绘制流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"位置读取与绘制流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"位置读取与绘制流程\"></figure><figure><figcaption><strong>立即定位与后续读取时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"立即定位与后续读取时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"立即定位与后续读取时序\"></figure></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>位置字段怎么用</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>坐标</td><td>latestLocation.lat / lng</td><td>必须是有限 JSON 数值，纬度 −90～90、经度 −180～180；数值字符串不接受，不使用演示点补位。</td></tr><tr><td>定位状态</td><td>latestLocation.locStatus、generalData.isGPS</td><td>locStatus 不能为 x（不区分大小写），且 isGPS 必须为 true；不能把非 GPS 自动标成 WiFi 或 LBS。</td></tr><tr><td>上报时间</td><td>latestLocation.dateTime 与 generalData.dateTime</td><td>两者必须是有效且相同的毫秒时间；当前接受 12–13 位数值或数字字符串，范围为 2000～2100 年。</td></tr><tr><td>坐标系统</td><td>latestLocation.coordinateSystem</td><td>缺字段才默认 WGS84；明确 null 或未知值不绘点。接受 WGS84 / GCJ02（含连字符形式），按地图服务转换一次；默认仍待后端确认。</td></tr><tr><td>指令响应</td><td>code=0、ok≠false、data 为非空字符串</td><td>仅确认服务端受理；不代表设备已执行、定位成功或位置已更新。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"refresh\"><h2><span class=\"guide-section-number\">4</span>刷新和失败怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>刷新位置</strong><p>前台轮询已有设备，离页 / 后台停止；正常数据更新保持用户拖动或缩放后的视野。</p></li><li><strong>主动回位</strong><p>只有明确的回到设备操作才主动调整视野；切换地图服务时重新按服务坐标规则绘制。</p></li><li><strong>指令拒绝</strong><p>服务端明确离线或拒绝时给出对应反馈，不能用成功 Toast 掩盖失败。</p></li><li><strong>指令结果不明</strong><p>超时、断网、响应不完整时不自动重发；按钮并发调用不排队，避免后续补发重复指令。</p></li><li><strong>旧位置</strong><p>允许展示有明确时间的最后上报，不推算移动；鉴权拒绝和关系失效后不继续沿用受限数据。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>后端待确认</strong><p>正式坐标系、时间类型及单位、立即定位的设备执行结果与超时规则。</p></li><li><strong>尚未验证完整</strong><p>真实硬件持续移动、轨迹、围栏和 Google 卫星图；原型轨迹与围栏不能作为已接入依据。</p></li><li><strong>下行与新位置</strong><p>10-20 HID 中继下立即定位收到真实设备 ACK，但没有产生新位置；TCP 模拟 A/B 数据仅证明模拟上报到 API / App 的更新链路。蜂窝直连和实际移动仍待验。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>HomeScreen.kt / CloudSubjectFilter.kt / CloudDeviceMapProjection.kt / RemoteAppDeviceLocationCommandRepository.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","account":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>账号资料与头像技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 保存和上传怎么走</a><a href=\"#fields\">3. 哪些字段可以改</a><a href=\"#failure\">4. 失败时怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>账号资料与头像技术说明</h1><p class=\"guide-lead\">本人资料只修改昵称、姓名和头像；保存时发送变化字段，完成独立回读后才更新页面。</p><p class=\"guide-scope\">这里是登录账号本人，不是家人 / 宠物档案。邮箱和手机号仅展示，不能直接套用完整 UserDTO 写入。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>获取本人资料</strong><span class=\"guide-api-route\"><b>GET</b><code>/user/info</code></span><small>进入页面、保存前及保存后读取</small></li><li><strong>保存变化字段</strong><span class=\"guide-api-route\"><b>PUT</b><code>/user/personal/edit</code></span><small>原 username + nickname / name / avatar 差量</small></li><li><strong>上传图片</strong><span class=\"guide-api-route\"><b>POST</b><code>/sys-file/upload</code></span><small>multipart/form-data，part 名称 file</small></li><li><strong>展示返回头像</strong><span class=\"guide-api-route\"><b>GET</b><code>服务端返回的头像 URL</code></span><small>动态返回 URL，使用不带 Token 的图片客户端</small></li></ol><div class=\"guide-notes\"><p>上传的实际调用为 multipart；公开文档中的 application/json 声明仍有差异。头像地址按环境和允许的来源校验，不向任意图片地址附带登录 Token。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>保存和上传怎么走</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>加载资料</strong><p>GET /user/info，保存当前账号、环境、username 及字段基线。</p></li><li><strong>编辑与预览</strong><p>昵称 / 姓名单项编辑；图片先本地预览，确认后才读取文件并上传。取消不发送保存请求。</p></li><li><strong>提交变化</strong><p>保存前重读资料以发现冲突；头像先上传取得地址，再 PUT 原 username 和变化字段。</p></li><li><strong>确认成功</strong><p>再次 GET /user/info，逐项核对本次变化；一致后更新资料页及“我的”展示。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>账号资料保存流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"账号资料保存流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"账号资料保存流程\"></figure><figure><figcaption><strong>头像上传与资料回读时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"头像上传与资料回读时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"头像上传与资料回读时序\"></figure></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>哪些字段可以改</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>昵称</td><td>nickname</td><td>当前客户端最多 80 个字符；空串可清空，不能用页面显示的兜底姓名覆盖原值。</td></tr><tr><td>姓名</td><td>name</td><td>当前客户端最多 80 个字符；只提交本次变化，空串与 null 分别处理。</td></tr><tr><td>头像</td><td>avatar</td><td>保存服务器返回的合法地址；移除发送空串。照护对象接口对应字段则是 avatarUrl。</td></tr><tr><td>用户名</td><td>username</td><td>带上保存前回读的本人原值；这是写入所需字段，不提供改用户名入口。</td></tr><tr><td>只读信息</td><td>email、phone 等</td><td>显示已有信息，不提交手机号、邮箱、地区、联系人或完整 UserDTO。</td></tr><tr><td>图片限制</td><td>PNG / JPEG，最多 5 MiB</td><td>校验文件签名、MIME 和解码尺寸；单边最多 8192、总像素最多 3200 万，当前不自动压缩。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>失败时怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>冲突</strong><p>待改字段或 username 与编辑基线不同，停止提交并要求刷新，避免覆盖其他入口的修改。</p></li><li><strong>保存未确认</strong><p>写入后超时、取消或回读不一致时先刷新资料，再允许继续保存，不自动重放写入。</p></li><li><strong>头像部分成功</strong><p>已经确认上传的地址可在同一上下文复用；上传本身未确认时不盲目重传同一图片。</p></li><li><strong>切账号或环境</strong><p>请求前后核对身份，清理或隔离缓存；旧账号头像不能写入新账号。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>接口问题</strong><p>后端仍需明确公共资料接口的 App 使用范围；缺 username、非空 phone 的错误及清空语义需修正 / 确认。</p></li><li><strong>文件策略</strong><p>头像公开读取、地址有效期、替换后的旧图及上传后未引用文件的回收规则待确认。</p></li><li><strong>验收边界</strong><p>本人头像的 JPEG、真实弱网和过期会话异常尚未完成真机验收；不能将客户端格式支持等同于端到端通过。</p></li><li><strong>既有证据</strong><p>10-09 本人昵称 / 姓名及 PNG 头像有保存、独立回读和重新登录记录；文件回收、本人 JPEG 和异常会话不随本文更新而新增通过。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>RemoteAccountRepository.kt / RemoteAccountProfileGateway.kt / AccountAvatarSource.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","login":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>登录与账号安全技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 业务流程怎么走</a><a href=\"#fields\">3. 参数怎么提交</a><a href=\"#failure\">4. 失败时怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>登录与账号安全技术说明</h1><p class=\"guide-lead\">登录先建立 OAuth 会话；注册和找回密码在最终提交时校验验证码，完成后返回登录页。</p><p class=\"guide-scope\">覆盖密码登录、会话恢复、注册、找回 / 修改密码及退出。本人资料编辑另见账号资料说明。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>登录或刷新 Token</strong><span class=\"guide-api-route\"><b>POST</b><code>/oauth2/token</code></span><small>同一路径，切换 grant_type；响应直接是 Token 对象</small></li><li><strong>显式校验当前会话</strong><span class=\"guide-api-route\"><b>GET</b><code>/token/check_token</code></span><small>按需调用；启动恢复不逐次请求此接口</small></li><li><strong>登录后补齐本人资料</strong><span class=\"guide-api-route\"><b>GET</b><code>/user/info</code></span><small>资料暂时不可读不否定已建立的会话</small></li><li><strong>发送注册 / 找回验证码</strong><span class=\"guide-api-route\"><b>GET</b><code>/sysMessage/send/app/emailCode</code></span><small>registered=false 注册，true 找回；GET 会发送邮件</small></li><li><strong>注册、找回和修改密码</strong><span class=\"guide-api-route\"><b>POST</b><code>/register/user</code></span><span class=\"guide-api-route\"><b>POST</b><code>/register/forget/{code}</code></span><span class=\"guide-api-route\"><b>POST</b><code>/register/password</code></span><small>分别使用对应请求体，不共用登录表单</small></li><li><strong>退出当前登录</strong><span class=\"guide-api-route\"><b>DELETE</b><code>/token/logout</code></span><small>请求远程退出，同时清理本地会话与当前对象选择</small></li></ol><div class=\"guide-notes\"><p>OAuth 登录 / 刷新使用配置生成的 Basic Authorization，以及 Enc-Flag=false、skipTenant=true、skipToken=true。业务 Bearer 头不能直接套用到取 Token 请求。</p><p>登录密码按当前 PasswordEncryptor 的 AES/CFB/NoPadding → Base64 处理；密钥 / IV 不写入文档。注册、找回、改密当前直接按各自 JSON DTO 传参，不能自行套用登录加密。</p><p>发码使用 App-Client-Id，注册 / 密码接口使用 X-Client-Id；所有客户端统一带 IANA 格式的 X-TimeZone。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>业务流程怎么走</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>密码登录</strong><p>校验输入，POST grant_type=password；校验 Token 响应，保存会话后读取 /user/info，再进入首页。</p></li><li><strong>启动恢复</strong><p>等待本地会话读取完成。有 Token 且到期时间超过当前 60 秒时直接恢复；否则使用 refresh_token 续期。</p></li><li><strong>注册 / 找回</strong><p>邮箱发码 → 输入 4 位码 → 填账号 / 新密码 → 最终 POST。验证码页只校验格式，没有独立验证码校验请求。</p></li><li><strong>修改密码</strong><p>使用当前会话的 username、原密码和新密码；成功后走退出流程，清理登录导航并要求重新登录。</p></li><li><strong>退出</strong><p>二次确认后请求 /token/logout；普通远程失败仍清理当前本地会话，旧退出回包不能清掉后来建立的新会话。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>启动与会话恢复流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"启动与会话恢复流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"启动与会话恢复流程\"></figure><figure><figcaption><strong>注册与找回密码时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"注册与找回密码时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"注册与找回密码时序\"></figure></div><div class=\"guide-notes\"><p>注册 / 找回完成后返回登录页并预填账号，不自动当作已经登录。刷新 Token 缺新 refresh_token 时保留原值。</p></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>参数怎么提交</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>OAuth 登录</td><td>query：username、grant_type=password、scope；表单：password</td><td>application/x-www-form-urlencoded；username 是登录账号，不用昵称替代。</td></tr><tr><td>OAuth 刷新</td><td>query：grant_type=refresh_token、scope；表单：refresh_token</td><td>刷新串放表单；access_token / expires_in 必须有效，expires_in 单位为秒，再换算 expiresAtMs。</td></tr><tr><td>注册</td><td>username、password、email、tenantId、code、registerType、loginType</td><td>当前 registerType=EMAIL、loginType=PWD；租户来自调用配置，不由输入表单任意指定。</td></tr><tr><td>找回 / 改密</td><td>找回：email、code、newpassword1 等；改密：username、password、newpassword1</td><td>找回路径 code 与 JSON code 一致；改密 username 取会话原值，不把邮箱当成已确认 username。</td></tr><tr><td>表单校验</td><td>username、password、confirmPassword、acceptedAgreement</td><td>注册用户名 4–20 位字母数字下划线；新密码至少 8 位且含大小写与数字；确认密码、协议勾选只用于本地校验。</td></tr><tr><td>发码节流</td><td>4 位验证码，60 秒重发倒计时</td><td>倒计时从发码成功开始；真实有效期、错误次数和频率限制仍由服务端确定。</td></tr></tbody></table></div><div class=\"guide-notes\"><p>公共命令接口按业务包装判定成功，data=null 不单独视为失败；OAuth Token 响应不能套用 ApiResponse 的解析器。</p></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>失败时怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>恢复失败</strong><p>刷新明确拒绝或没有 refresh_token 时清当前会话并回登录；临时网络 / 服务端失败保留会话，界面仍可进入，业务区域提示失败与重试。</p></li><li><strong>读取遇到过期</strong><p>普通网络层只对 GET / HEAD 的 HTTP 401 或约定的 token expired 424 刷新；同一会话的并发刷新合并，成功后重发该读取一次。</p></li><li><strong>写入遇到过期 / 超时</strong><p>POST / PUT / PATCH / DELETE 不套用自动刷新重放；结果不明时先核对，避免重复注册、修改或发送业务指令。</p></li><li><strong>验证码错误</strong><p>最终提交提示验证码错误 / 过期时返回验证码步骤，保留账号表单；其他错误留在当前步骤，发送和提交期间禁用重复点击。</p></li><li><strong>切账号 / 环境</strong><p>刷新保存与退出清理核对会话版本，过时回包不覆盖新登录。Token、密码、验证码及客户端密钥不进入导出或日志。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>后端待确认</strong><p>公共账号接口的 App 使用范围、OAuth / 加密参数、验证码有效期及限流错误码、多终端会话撤销规则。</p></li><li><strong>尚未接入</strong><p>第三方登录 / 绑定、账号注销、登录设备管理；原型对应按钮不能作为正式能力依据。</p></li><li><strong>验证边界</strong><p>注册 / 找回已有用户实测记录；本轮只对照代码整理，未发邮件或修改密码。过期、弱网、切账号等分支仍需按当前制品真机验收。</p></li><li><strong>既有证据</strong><p>09-28 注册、邮箱发码和找回密码为用户实测确认；租户 / 角色映射与全部会话异常仍需独立验证。本轮未发送邮件或修改账号。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>OAuthTokenApi.kt / OAuthSessionManager.kt / TokenRefreshInterceptor.kt / PublicAccountClient.kt / AuthFlowViewModel.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","chat":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>AI 客服技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 一条消息怎么完成</a><a href=\"#fields\">3. 字段和事件怎么用</a><a href=\"#failure\">4. 取消和重试怎么处理</a><a href=\"#gaps\">5. 哪些内容还要补</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>AI 客服技术说明</h1><p class=\"guide-lead\">先创建问题取得 messageId，再用 SSE 逐段接收回答；停止、失败和完成分别处理。</p><p class=\"guide-scope\">说明通用客服会话。设备概览、健康和告警的 AI 分析已在设备详情说明中，使用另一组接口。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>读取当前默认模型</strong><span class=\"guide-api-route\"><b>GET</b><code>/aiModel/list</code></span><small>进入聊天预取；发送时按缓存情况再读取</small></li><li><strong>创建用户问题</strong><span class=\"guide-api-route\"><b>POST</b><code>/chat/create</code></span><small>POST 返回 messageId 字符串，不是完整回答</small></li><li><strong>读取该问题的回答流</strong><span class=\"guide-api-route\"><b>GET</b><code>/chat/msg/list</code></span><small>query：key=messageId；Accept: text/event-stream</small></li></ol><div class=\"guide-notes\"><p>请求使用当前环境地址、Bearer Token、TENANT-ID、lang 和 X-TimeZone；租户来自 AI 配置，lang 每次读取 App 当前语言。</p><p>模型列表按环境 / 租户 / 用户缓存 10 分钟。根据模式选择 Chat 或 Reason 类型，优先服务端 defaultModel，再选该类型首个模型。读取失败可用旧缓存 / 内置兜底；成功列表缺所需类型则明确提示不可用。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>一条消息怎么完成</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>准备会话</strong><p>每种模式维护独立 conversationId、输入和消息；同一模式已有请求时禁止再次发送，创建用户消息和等待中的回答占位。</p></li><li><strong>创建问题</strong><p>选择模型并提交 /chat/create；先判 HTTP 和业务响应，再把 data 解析为 Long messageId，用其字符串值作为流读取 key。</p></li><li><strong>读取回答</strong><p>打开 SSE，将回答、推理、工具和来源映射为不同事件；只更新该模式、该回答占位，不重复创建气泡。</p></li><li><strong>收尾</strong><p>完成转为已结束；网络失败保留已收内容并标失败。用户停止或离开页面取消流，保留内容并标 STOPPED。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>AI 消息处理流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"AI 消息处理流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"AI 消息处理流程\"></figure><figure><figcaption><strong>创建消息与流式回答时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"创建消息与流式回答时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"创建消息与流式回答时序\"></figure></div><div class=\"guide-notes\"><p>切换模式只切换展示，旧模式请求可以继续；退出聊天或更换设备 / 告警入口时停止全部模式请求。</p></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>字段和事件怎么用</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>会话与消息</td><td>conversationId；POST 返回 data → messageId → GET key</td><td>conversationId 当前按模式生成 UUID 会话串；messageId 不是本地气泡 ID。数值 ID 保持无损，不经浮点数转换。</td></tr><tr><td>问题内容</td><td>role=user、content、time、modelName</td><td>content 去首尾空白；time 按手机时区生成 yyyy-MM-dd HH:mm:ss；modelName 来自模型选择结果。</td></tr><tr><td>模式与上下文</td><td>datasetId、tenantId、extDetails、websearch、inner</td><td>四模式 datasetId 为 0 / -3 / -7 / -8；extDetails 带用户 / 租户，MCP 另需 mcpId；当前 websearch=false、inner=false。</td></tr><tr><td>SSE 正文</td><td>纯文本 / delta；content、answerText 等累计文本</td><td>纯文本和 delta 追加；累计快照提取新增部分，重复内容不重复展示；推理 reasoningContent 单独显示。</td></tr><tr><td>工具与来源</td><td>toolInfo / toolInfoList；extLinks</td><td>工具按内容去重，来源按 URL 或标题去重；正文、推理、工具、来源不混为一种文本。</td></tr><tr><td>完成信号</td><td>done / complete、[DONE]、finish / finished</td><td>去掉结尾完成标记；当前正常关闭且已收到有效片段也作完成，空流失败。HTTP 200 建立连接不代表已收到回答。</td></tr><tr><td>请求语言</td><td>公共 lang 与消息 languageTag 快照</td><td>发送时固定语言供 POST / SSE 使用，切语言不把已有流改成另一语言；界面语言和用户提问语言的策略分开判断。</td></tr></tbody></table></div><div class=\"guide-notes\"><p>当前请求体不发送 temperature、top_p、max_tokens 或 systemPrompt；不能把其他 AI SDK 的默认参数当成本接口字段。</p></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>取消和重试怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>发送 / 流失败</strong><p>空 messageId、非法 ID、业务失败及 SSE 错误均标失败；已有正文保留，并解除当前模式发送限制。</p></li><li><strong>手动重试</strong><p>失败气泡可重试：在同一会话重新 POST 原问题，取得新 messageId；保留原用户气泡，替换失败的回答占位，不是从旧流断点继续。</p></li><li><strong>主动停止</strong><p>先发布 STOPPED 状态，再取消 SSE；无内容显示已停止，有内容保留已收部分。停止本地连接不证明服务器已停止生成。</p></li><li><strong>返回恢复</strong><p>同一账号 / 环境 / 入口可恢复进程内快照和输入；旧 STREAMING 改为 STOPPED，不自动恢复流。进程被杀后没有服务端历史恢复能力。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>哪些内容还要补</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>设备上下文</strong><p>当前设备 / 告警入口用于本地会话隔离，未发送类型化设备、对象或告警字段；不能据此声称 AI 已读取该设备实时数据。</p></li><li><strong>服务端契约</strong><p>消息历史、断点续传、停止生成、错误事件和正常关闭的统一规则，以及人工客服 / 工单入口仍需确认。</p></li><li><strong>验证边界</strong><p>本轮只对照代码，不新增 AI 请求。四模式模型 / MCP 可用性、发送期间切账号或环境、真实弱网与长流需独立验收。</p></li><li><strong>已有语言验证</strong><p>10-21 自由模式英文问答通过；中文界面下 MCP 英文提问仍返回中文，知识库缺可访问内容，均保持待确认。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>AiAssistantClient.kt / AiAssistantSseParser.kt / ChatRepository.kt / ChatViewModel.kt / ChatConversationSessionStore.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","configuration":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>网络与蓝牙统一设备配置技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 业务流程怎么走</a><a href=\"#fields\">3. 哪些字段可以操作</a><a href=\"#failure\">4. 失败和迟到结果怎么处理</a><a href=\"#gaps\">5. 已验证与待补内容</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>网络与蓝牙统一设备配置技术说明</h1><p class=\"guide-lead\">同一物模型菜单和表单选择网络或蓝牙渠道；保存前读取真实完整组，保存后独立回查，渠道切换清除旧基线。</p><p class=\"guide-scope\">当前复用原 EV07B 物模型的 28 项菜单，菜单存在不等于两个渠道均可读写。网络仅开放低电量阈值和短信前缀保存；其他字段只读或禁用。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>核对设备产品</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/product</code></span><small>自有关系确认后选择支持的物模型包</small></li><li><strong>读取设备完整参数组</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/property</code></span><small>GET query：property=powerLowAlert 等组名</small></li><li><strong>保存允许修改的完整组</strong><span class=\"guide-api-route\"><b>POST</b><code>/app/device/{deviceId}/property</code></span><small>POST JSON：组名包裹完整原始组，仅替换允许字段</small></li></ol><div class=\"guide-notes\"><p>BLE 复用原 GATT / 协议映射和风险确认；没有独立的“蓝牙 HTTP 保存接口”。</p><p>Prod 使用正式 App property runtime，不启用历史 /c/v1 占位云网关。页面按账号、环境、设备和所选渠道隔离数据。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>业务流程怎么走</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>进入与读取</strong><p>确认自有关系和产品，从同一设备配置入口打开原菜单；按所选渠道读取当前页所需参数组，缺失值不填默认值。</p></li><li><strong>编辑与切换</strong><p>仅允许当前渠道支持的字段编辑。切换网络 / 蓝牙前确认放弃草稿，取消旧请求，清空值、基线和风险确认，再重读同页。</p></li><li><strong>保存前核对</strong><p>网络先重读完整组并比较编辑基线；冲突停止。保留未知字段与同组其他值，只替换本次允许变化。BLE 按原整组和风险守卫执行。</p></li><li><strong>提交与确认</strong><p>一次下发后做独立读取核对；POST 回显不充当读回，硬件 ACK 也不代替完整参数核对。超时先查实际状态，不自动再发。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>统一配置与渠道切换流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"统一配置与渠道切换流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"统一配置与渠道切换流程\"></figure><figure><figcaption><strong>网络保存与独立回查时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"网络保存与独立回查时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"网络保存与独立回查时序\"></figure></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>哪些字段可以操作</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>低电量</td><td>powerLowAlert.power</td><td>网络只修改阈值，不自动开启提醒；status 与未改字段保持，SDK 派生 flag 按阈值差量核对。</td></tr><tr><td>短信前缀</td><td>smsOption.prefix</td><td>网络只改 prefix；保留短信开关、密码及其他原始成员，不把联系人页整体视为可写。</td></tr><tr><td>定位上报</td><td>timeInterval、workMode、heartBeat</td><td>当前网络只读；上传组保存被 Parameter error 拒绝，页面与 Native 均阻止上传间隔编辑。</td></tr><tr><td>联系人和通话</td><td>number、sosOption、phoneOption、smsOption</td><td>网络读取已接入，联系人位置和空项保留；号码、SOS、通话及短信开关不开放保存。</td></tr><tr><td>其他物模型项</td><td>原菜单属性、页面和 BLE 映射</td><td>网络没有映射的字段原位禁用；蓝牙支持情况按产品 / 固件、连接和执行守卫判断。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>失败和迟到结果怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>渠道迟到回包</strong><p>切换后旧渠道的读结果、状态查询和缓存不覆盖当前渠道；请求代数及读取 token 必须仍匹配。</p></li><li><strong>离线或不可读</strong><p>显示明确离线 / 不支持，不用旧渠道数值或默认值伪装新读值；缺基线、保存中或不可读时禁用保存。</p></li><li><strong>冲突或结果不明</strong><p>重读基线不同即停止；取消、超时、回包缺失或独立回查不一致时要求重新读取，不自动重放写入。</p></li><li><strong>权限和业务拒绝</strong><p>Parameter error 按参数拒绝展示，不误报为用户无权限；身份或环境改变后拒绝旧操作。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>已验证与待补内容</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>已有网络保存</strong><p>10-22 指定 EV07BA 的低电量 30→29→30、短信前缀原值→测试值→原值，有 App、真实 ACK、独立 API / HID 和恢复记录。</p></li><li><strong>统一页面验证</strong><p>10-23 同一 28 项菜单及网络低电量、工作模式、联系人组合读取通过，参数和绑定保持；该轮未保存参数。</p></li><li><strong>BLE 当前边界</strong><p>10-20 有身份与低电量 / Server 保存恢复记录；10-23 新旧入口同设备对照均报 BLE_GATT_UNAVAILABLE，不把旧缓存计为本轮读取通过。</p></li><li><strong>仍待完成</strong><p>上传组服务端拒绝、其他字段逐项读写 / ACK / 恢复、其他型号固件和稳定性、真实蜂窝直连。HID 中继只证明该中继链路。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>AppCloudConfigContract.kt / RemoteAppCloudConfigRuntime.kt / RemoteAppDeviceCloudConfigRepository.kt / DeviceConfigBridgeActions.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","sharing":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>设备分享技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 业务流程怎么走</a><a href=\"#fields\">3. 参数和状态怎么区分</a><a href=\"#failure\">4. 异常和失权怎么处理</a><a href=\"#gaps\">5. 已验证与待补内容</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>设备分享技术说明</h1><p class=\"guide-lead\">所有者创建设备邀请，接收人接受后按有效权限读取；修改、重发、撤销均回查状态，撤销或到期后清除受限数据。</p><p class=\"guide-scope\">仅支持 DEVICE 设备分享。不提供人员或宠物档案分享，也不从档案授权继承设备；历史 PERSON/PET 邀请被过滤，服务器旧授权不自动删除。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>解析接收人账号</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/shares/grantee</code></span><small>GET query：account；结果区分已注册与未注册</small></li><li><strong>创建设备邀请</strong><span class=\"guide-api-route\"><b>POST</b><code>/app/device/{deviceId}/shares</code></span><small>POST 路径传 deviceId，body 传接收人、角色、权限和有效期</small></li><li><strong>读取当前账号收到 / 发出的邀请</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/shares/received</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/subjects/shares/granted</code></span><small>服务端一次返回列表，App 按 DEVICE、资源与当前参与者过滤</small></li><li><strong>接受或拒绝邀请</strong><span class=\"guide-api-route\"><b>POST</b><code>/app/subjects/shares/{shareId}/accept</code></span><span class=\"guide-api-route\"><b>POST</b><code>/app/subjects/shares/{shareId}/reject</code></span><small>按 shareId 提交一次，再回查列表中的记录</small></li><li><strong>修改、重发和撤销</strong><span class=\"guide-api-route\"><b>PATCH</b><code>/app/device/{deviceId}/shares/{shareId}</code></span><span class=\"guide-api-route\"><b>POST</b><code>/app/device/{deviceId}/shares/{shareId}/resend</code></span><span class=\"guide-api-route\"><b>DELETE</b><code>/app/subjects/shares/{shareId}</code></span><small>DEVICE 修改 / 重发走设备路径；撤销走通用 subjects/shares 路径</small></li><li><strong>按授权查看共享设备</strong><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/state</code></span><span class=\"guide-api-route\"><b>GET</b><code>/app/device/{deviceId}/realtime</code></span><small>只读取允许的 PROFILE / LOCATION 数据；不开放自有设备命令</small></li></ol><div class=\"guide-notes\"><p>路径出现 /app/subjects/shares 不表示允许分享人员档案；业务资源仍为 DEVICE。</p><p>不使用管理端 ShareGrant CRUD 拼装邀请流程；接受、拒绝、重发和撤销都使用正式 App 命令。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>业务流程怎么走</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>创建</strong><p>所有者进入设备分享管理，解析接收人。已注册传 granteeUserId，未注册传 inviteAccount；选择角色、scopes 和有效期，提交一次并回查发出记录。</p></li><li><strong>接收处理</strong><p>消息页只展示 DEVICE 邀请，只有目标接收人可处理有效待处理记录；接受 / 拒绝后以重新读取的状态确认。</p></li><li><strong>共享查看</strong><p>设备列表展示直接分享设备，按当前接收人、ACCEPTED、未撤销和未到期筛选；同一设备合并有效 scopes，不将设备授权扩展为档案访问权。</p></li><li><strong>修改与结束</strong><p>所有者修改、重发或撤销后重新读记录；接收人刷新、恢复或重新进入时重新校验，失权后清除受限数据。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>设备分享状态与读取流程</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"设备分享状态与读取流程\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"设备分享状态与读取流程\"></figure><figure><figcaption><strong>双账号创建接受与撤销时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"双账号创建接受与撤销时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"双账号创建接受与撤销时序\"></figure></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>参数和状态怎么区分</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>设备和邀请</td><td>deviceId / shareId</td><td>deviceId 指资源；shareId 指邀请 / 授权记录，二者不互换。</td></tr><tr><td>接收人</td><td>granteeUserId / inviteAccount</td><td>已注册与未注册分支互斥，不能把邮箱或手机号当作用户 ID。</td></tr><tr><td>权限</td><td>role / scopes</td><td>界面角色与数据 scopes 分开校验；只读共享页面按实际有效授权决定可见区域，不据角色标签推定所有命令可用。</td></tr><tr><td>有效期</td><td>expiresAt / clearExpiresAt</td><td>创建可省略有效期；修改清除有效期显式传 clearExpiresAt，不能用省略或 null 冒充清除。</td></tr><tr><td>状态</td><td>PENDING / ACCEPTED / REJECTED / REVOKED / EXPIRED</td><td>以重新读取的记录和当前时间共同判断；保留未注册邀请，不伪造接收人 ID。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>异常和失权怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>未确认命令</strong><p>连接失败、超时或回查状态不符时保持未确认，不自动重发邀请或接受 / 撤销命令。</p></li><li><strong>旧档案目标</strong><p>PERSON/PET 创建、修改、重发在本地拒绝；旧邀请不显示，旧共享档案导航只返回。</p></li><li><strong>权限消失</strong><p>每次共享读取前后确认有效授权；权限拒绝、撤销、到期或账号 / 环境变化后清除旧受限结果。</p></li><li><strong>展示缺字段</strong><p>缺接收人名称或设备名称时按既定回退展示，不使用本地演示人物补齐服务端数据。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>已验证与待补内容</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>已有真机记录</strong><p>10-19 81 环境 DEVICE LOCATION-only 创建、接受、读取、撤销失权有双账号手机记录；10-20 所有者手机重发、修改 / 清除有效期、撤销通过，接收方未复验。</p></li><li><strong>范围调整</strong><p>10-21 移除档案分享入口与继承设备发现，旧目标零请求和混合回包过滤有本地测试；该轮未新增服务器分享命令。</p></li><li><strong>仍待验收</strong><p>其他 scopes / MANAGER、有效期修改及到期、未注册后注册接收、完整异常链、租户 / 普通用户权限和邀请展示字段。</p></li><li><strong>推送另算</strong><p>收件箱可读取不代表推送到达；FCM/HMS、后台到达、点击落点与告警处理仍待接入。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>ShareManagementViewModel.kt / AppShareCreationApiService.kt / ShareInvitationApiService.kt / SharedDeviceReader.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","finding":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>云端查找设备技术说明</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#apis\">1. 用哪些接口</a><a href=\"#flow\">2. 业务流程怎么走</a><a href=\"#fields\">3. 字段和结果怎么看</a><a href=\"#failure\">4. 离线和超时怎么处理</a><a href=\"#gaps\">5. 已验证与待补内容</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>云端查找设备技术说明</h1><p class=\"guide-lead\">自有设备详情点击“查找”，App 只发送一次 findMe；服务器受理、硬件 ACK 和现场声音分开确认。</p><p class=\"guide-scope\">查找用于让设备响铃或提示，不获取新 GPS。原型按钮仅显示演示提示，本专题从设备详情说明及说明目录独立打开。</p></header><section class=\"guide-section\" id=\"apis\"><h2><span class=\"guide-section-number\">1</span>用哪些接口</h2><div class=\"guide-section-body\"><ol class=\"guide-api-list\"><li><strong>向自有设备发送查找命令</strong><span class=\"guide-api-route\"><b>POST</b><code>/app/device/{deviceId}/function</code></span><small>POST /function?functionId=findMe，JSON body：{}</small></li></ol><div class=\"guide-notes\"><p>App 先确认当前账号自有关系与设备 ID；页面和 Repository 同时禁止并发重复发送。请求使用当前环境和会话快照。</p><p>立即定位使用同一路径的 singleLocating，但属于另一个业务；本次查找不替代定位更新。</p></div></div></section><section class=\"guide-section\" id=\"flow\"><h2><span class=\"guide-section-number\">2</span>业务流程怎么走</h2><div class=\"guide-section-body\"><ol class=\"guide-steps\"><li><strong>点击与预检</strong><p>所有者在详情点击查找，检查当前设备关系、页面忙碌状态和账号 / 环境，发送中禁用重复操作。</p></li><li><strong>下发请求</strong><p>以 functionId=findMe 和 {} 发送一次 POST；设备、会话或环境变化后拒绝旧响应。</p></li><li><strong>页面反馈</strong><p>HTTP 与业务返回有效、data 为非空文本时提示请求已发送，请留意设备提示音；不直接显示响铃成功。</p></li><li><strong>效果核对</strong><p>联调时另查设备真实 ACK，并由现场人员确认声音。重新进入、刷新或冷启动不自动重发命令。</p></li></ol><div class=\"guide-diagrams\"><figure><figcaption><strong>查找命令与验证层次</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"查找命令与验证层次\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"查找命令与验证层次\"></figure><figure><figcaption><strong>查找请求和设备声音时序</strong><button class=\"guide-button\" type=\"button\" data-guide-figure data-guide-title=\"查找请求和设备声音时序\">放大图表</button></figcaption><img src=\"data:image/svg+xml;base64,\" alt=\"查找请求和设备声音时序\"></figure></div></div></section><section class=\"guide-section\" id=\"fields\"><h2><span class=\"guide-section-number\">3</span>字段和结果怎么看</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>资源</td><td>deviceId</td><td>仅当前账号确认的自有设备，不从共享只读页面触发。</td></tr><tr><td>指令</td><td>functionId=findMe；body={}</td><td>不附带坐标，不复用参数配置 payload，也不更改设备配置。</td></tr><tr><td>回执</td><td>code=0、ok≠false、data 非空字符串</td><td>仅确认正式接口已受理；设备 ACK 和真实声音需另行核对。</td></tr><tr><td>位置</td><td>realtime 的 latestLocation</td><td>查找本身不产生新位置结论；GPS 更新属于地图与立即定位专题。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"failure\"><h2><span class=\"guide-section-number\">4</span>离线和超时怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>离线</strong><p>根据中英文业务消息识别 Device is offline / 设备离线，提示设备离线，不误报普通网络失败。</p></li><li><strong>拒绝与失权</strong><p>无自有关系、鉴权拒绝或业务拒绝不报告发送成功；当前会话变化则丢弃旧反馈。</p></li><li><strong>结果不明</strong><p>超时、断网、响应不完整或缺必要字段保持未确认；不自动重试，先确认设备是否已响铃再手动决定。</p></li><li><strong>重进与冷启动</strong><p>显示读取状态，不回放历史查找命令；发送互斥不把重复点击排队到稍后补发。</p></li></ul></div></section><section class=\"guide-section\" id=\"gaps\"><h2><span class=\"guide-section-number\">5</span>已验证与待补内容</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>已有实机证据</strong><p>10-20 云端 HID 中继收到真实查找 ACK，用户确认听到声音；10-21 新 App 首轮查找也获成功 ACK 与用户听音确认。</p></li><li><strong>最终包边界</strong><p>10-21 最终修复包第二次查找 ACK 和页面通过，用户回复“刚才未留意”，该次声音未确认；离线、重进和冷启动未重发有记录。</p></li><li><strong>仍待验收</strong><p>最终包现场声音补验、真实蜂窝直连、其他型号 / 固件与全部网络异常。中继只证明服务器—电脑—真实设备链路。</p></li></ul></div></section><p class=\"guide-shared-note\">公共约定：业务请求带 Bearer Token 与 IANA 格式的 X-TimeZone；ID 保持无损，写入结果不明时先回查。认证、图片等专用客户端按各自规则处理。</p><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>CloudDeviceDetailViewModel.kt / RemoteAppDeviceFindCommandRepository.kt / AppDeviceFindCommandApi.kt<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n","common":"<!doctype html>\n<!-- 自动生成：修改 business-guides.js 后运行 node scripts/build-business-guides.cjs -->\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><link rel=\"icon\" href=\"data:,\"><title>公共接口约定</title><style>/* 说明工具只影响原型外围与离线文档，不改变手机内的业务布局。 */\n.guide-page-panel { display: grid; gap: 16px; min-width: 0; }\n.guide-page-panel[hidden], .business-guide[hidden], .guide-mobile-nav[hidden] { display: none; }\n.guide-tabs { position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 4px; border: 1px solid #dce3e8; border-radius: 10px; background: #eef3f5; }\n.guide-tabs button { flex: 1; min-height: 44px; border: 0; border-radius: 7px; color: #536472; background: transparent; font: inherit; font-size: 14px; cursor: pointer; }\n.guide-tabs [aria-selected=\"true\"] { color: #075c58; font-weight: 700; background: white; box-shadow: 0 1px 4px #182c3914; }\n.business-guide { display: grid; gap: 12px; min-width: 0; color: #18212b; font: 13px/1.7 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.business-guide *, .guide-dialog *, .guide-mobile-nav { box-sizing: border-box; }\n.business-guide p { margin: 0; }\n.business-guide code { overflow-wrap: anywhere; font: 0.92em/1.6 Consolas, \"Microsoft YaHei\", monospace; color: #285264; background: #edf3f6; border-radius: 3px; padding: 1px 3px; }\n.guide-card, .guide-section { min-width: 0; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; }\n.guide-card { padding: 18px; }\n.guide-intro { border-color: #b2d6d3; }\n.guide-kicker { display: block; color: #526575; font-size: 11px; }\n.guide-card h2, .guide-card h1 { margin: 7px 0 12px; font-size: 22px; line-height: 1.4; }\n.business-guide .guide-lead { color: #223d48; font-size: 14px; font-weight: 600; }\n.business-guide .guide-scope { margin-top: 10px; color: #526575; font-size: 12px; }\n.guide-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n.guide-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 8px 12px; border: 1px solid #b8cfce; border-radius: 6px; color: #075c58; background: #fff; font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }\n.guide-button:hover { background: #eaf5f3; }\n.guide-actions .guide-button { flex: 1; white-space: nowrap; }\n.guide-section > summary { position: relative; padding: 13px 34px 13px 16px; cursor: pointer; list-style: none; }\n.guide-section > summary::-webkit-details-marker { display: none; }\n.guide-section > summary::after { content: \"+\"; position: absolute; right: 15px; top: 13px; color: #526575; font-size: 18px; }\n.guide-section[open] > summary::after { content: \"−\"; }\n.guide-section > summary > span { display: flex; align-items: center; font-size: 14px; font-weight: 650; }\n.guide-section > summary > small { display: block; padding-left: 26px; margin-top: 3px; font-size: 11px; color: #526575; }\n.guide-section-number { display: inline-flex; flex: 0 0 20px; align-items: center; justify-content: center; width: 20px; height: 20px; margin-right: 6px; border-radius: 5px; color: #075c58; background: #e5f2ef; font-size: 11px; }\n.guide-section-body { padding: 14px 16px; border-top: 1px solid #e7edef; }\n.guide-steps { margin: 0; padding-left: 22px; }\n.guide-steps li { padding-left: 2px; margin-bottom: 12px; }\n.guide-steps li:last-child { margin-bottom: 0; }\n.guide-steps li::marker { color: #0c756f; font-weight: 700; }\n.guide-steps p, .guide-rules p { margin-top: 3px; color: #526575; }\n.business-guide .guide-example { margin-top: 16px; padding: 10px 12px; border-left: 3px solid #0c756f; background: #edf6f4; color: #28524f; }\n.guide-diagrams { display: grid; gap: 8px; margin-top: 16px; }\n.guide-diagrams > .guide-button { justify-content: space-between; }\n.guide-api-list { list-style: none; margin: 0; padding: 0; }\n.guide-api-list li + li { margin-top: 14px; padding-top: 14px; border-top: 1px solid #e7edef; }\n.guide-api-route { display: flex; align-items: baseline; gap: 8px; margin: 4px 0; }\n.guide-api-route b { color: #335c9a; font-size: 10px; }\n.guide-api-route code { min-width: 0; }\n.guide-api-list small { color: #526575; }\n.guide-fields { margin: 0; }\n.guide-fields > div + div { margin-top: 12px; padding-top: 12px; border-top: 1px solid #e7edef; }\n.guide-fields dt { margin-bottom: 3px; font-weight: 650; }\n.guide-fields dd { margin: 0; color: #526575; }\n.guide-fields dd p { margin-top: 4px; }\n.guide-rules { list-style: none; padding: 0; margin: 0; }\n.guide-rules li + li { margin-top: 16px; }\n.guide-notes { margin-top: 16px; padding-top: 12px; border-top: 1px solid #e7edef; color: #526575; font-size: 12px; }\n.guide-notes p + p { margin-top: 8px; }\n.guide-footnote { padding: 6px 4px 12px; font-size: 11px; color: #526575; overflow-wrap: anywhere; }\n.guide-empty h2 { font-size: 20px; }\n.business-guide .guide-muted { margin-top: 14px; color: #526575; font-size: 12px; }\n.guide-tabs button:focus-visible, .business-guide :is(a, button, summary, [tabindex]):focus-visible, .guide-dialog button:focus-visible, .guide-mobile-nav a:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.demo-panel > [role=\"tabpanel\"]:focus-visible { outline: 3px solid #0c756f; outline-offset: -3px; }\n.guide-mobile-nav { display: none; }\n.guide-library-links { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 4px; }\n.guide-library-links a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; font-size: 12px; }\n.guide-library-links a:hover { text-decoration: underline; }\n.guide-related-links { display: grid; grid-template-columns: minmax(0, 1fr); }\n.guide-related-links > div { display: flex; align-items: center; gap: 8px; }\n.guide-related-links a { flex: 1; min-width: 0; }\n.guide-related-links button { flex: 0 0 auto; }\n.business-guide .guide-shared-note { padding: 12px 16px; border: 1px solid #dce3e8; border-radius: 8px; color: #526575; font-size: 12px; background: #f5f9f9; }\n.guide-library-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }\n.guide-library-grid a { display: block; padding: 20px; border: 1px solid #dce3e8; border-radius: 8px; background: #fff; color: #18212b; text-decoration: none; }\n.guide-library-grid a:hover { border-color: #0c756f; background: #f5fbfa; }\n.guide-library-grid strong { display: block; margin-bottom: 8px; color: #075c58; font-size: 17px; }\n.guide-library-grid p { color: #526575; font-size: 13px; }\n.guide-dialog { width: 96vw; height: 92dvh; max-width: 1440px; max-height: none; padding: 0; border: 1px solid #dce3e8; border-radius: 10px; color: #18212b; background: #fff; font: 14px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n.guide-dialog::backdrop { background: #142631b8; }\n.guide-dialog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid #dce3e8; background: #f1f6f7; }\n.guide-dialog-toolbar > div { display: flex; align-items: center; gap: 8px; }\n.guide-dialog-toolbar output { min-width: 38px; text-align: center; font-size: 12px; }\n.guide-dialog-toolbar button { min-width: 44px; }\n.guide-dialog-scroll { height: calc(100% - 65px); overflow: auto; padding: 20px; }\n.guide-dialog-scroll img { display: block; max-width: none; height: auto; margin: auto; }\n/* 生成的完整文档与下载版使用同一份 CSS。 */\nbody.guide-document { margin: 0; background: #f2f6f8; }\n.guide-document .business-guide { max-width: 980px; margin: 0 auto; padding: 32px 24px 56px; gap: 24px; font-size: 15px; }\n.guide-document .guide-card { padding: 28px 32px; }\n.guide-document .guide-card h1 { font-size: 30px; }\n.guide-document .guide-lead { font-size: 17px; }\n.guide-document .guide-scope { font-size: 14px; }\n.guide-document-nav { display: flex; flex-wrap: wrap; gap: 8px; }\n.guide-document-nav a { display: inline-flex; align-items: center; min-height: 44px; padding: 6px 10px; color: #075c58; text-decoration: none; font-size: 13px; border: 1px solid #cbdcdd; border-radius: 6px; background: #fff; }\n.guide-document .guide-section > h2 { display: flex; align-items: center; margin: 0; padding: 20px 26px; font-size: 20px; line-height: 1.5; }\n.guide-document .guide-section-number { width: 24px; height: 24px; flex-basis: 24px; margin-right: 10px; font-size: 13px; }\n.guide-document .guide-section-body { padding: 24px 26px; }\n.guide-document .guide-api-route code { font-size: 14px; }\n.guide-document figure { margin: 8px 0 0; border: 1px solid #dce3e8; border-radius: 8px; overflow: hidden; }\n.guide-document figcaption { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; font-size: 13px; background: #f1f6f7; }\n.guide-document figure > img { display: block; width: auto; height: auto; max-width: 100%; margin: auto; padding: 20px; }\n.guide-table-scroll { overflow-x: auto; }\n.guide-table-scroll table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.guide-table-scroll th, .guide-table-scroll td { min-width: 110px; padding: 12px; text-align: left; vertical-align: top; border-bottom: 1px solid #dce3e8; overflow-wrap: anywhere; }\n.guide-table-scroll th { color: #285264; background: #edf3f6; }\n.guide-table-scroll td:nth-child(2) { width: 28%; font-family: Consolas, \"Microsoft YaHei\", monospace; }\n.guide-document .guide-notes { font-size: 13px; }\n.guide-document .guide-footnote { font-size: 12px; }\n.guide-print-row { text-align: right; }\n@media (min-width: 901px) and (max-width: 1120px) {\n  .prototype-stage { grid-template-columns: minmax(360px, 414px) minmax(300px, 400px); }\n  .prototype-stage > .api-panel { grid-column: 1 / -1; max-height: 320px; }\n}\n@media (max-width: 520px) {\n  .guide-library-grid { grid-template-columns: 1fr; }\n  .guide-mobile-nav { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 12px; border-bottom: 1px solid #c7d9d9; background: #e8f1f1; font: 12px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .guide-mobile-nav span { color: #526575; }\n  .guide-mobile-nav a { display: inline-flex; align-items: center; min-height: 44px; color: #075c58; text-decoration: none; }\n  body:has(.guide-mobile-nav:not([hidden])) .phone-shell { height: calc(100dvh - 44px); }\n  .guide-document .business-guide { padding: 16px 12px 32px; gap: 16px; font-size: 14px; }\n  .guide-document .guide-card { padding: 20px; }\n  .guide-document .guide-card h1 { font-size: 25px; }\n  .guide-document .guide-section > h2 { padding: 16px; font-size: 17px; }\n  .guide-document .guide-section-body { padding: 16px; }\n  .guide-dialog-toolbar { flex-wrap: wrap; padding: 8px 12px; gap: 6px; }\n  .guide-dialog-toolbar > strong { width: 100%; }\n  .guide-dialog-toolbar > div { width: 100%; justify-content: space-between; gap: 4px; }\n  .guide-dialog-toolbar .guide-button { padding: 6px 10px; }\n  .guide-dialog-scroll { height: calc(100% - 90px); }\n}\n@media print {\n  .guide-document { background: #fff; }\n  .guide-document .business-guide { display: block; padding: 0; font-size: 10pt; }\n  .guide-document .guide-document-nav, .guide-document .guide-print-row, .guide-document .guide-button, .guide-dialog { display: none !important; }\n  .guide-document .guide-card, .guide-document .guide-section { border: 0; }\n  .guide-document .guide-section > h2 { break-after: avoid; }\n  .guide-document figure { break-inside: avoid; }\n  .guide-document figure > img { max-height: 235mm; object-fit: contain; }\n  .guide-document .guide-section-body, .guide-document .guide-card { padding: 12px 0; }\n  @page { size: A4; margin: 16mm; }\n}\n</style></head>\n<body class=\"guide-document\"><main class=\"business-guide\"><div class=\"guide-print-row\"><button class=\"guide-button\" type=\"button\" data-guide-print>打印 / 保存 PDF</button></div><nav class=\"guide-document-nav\" aria-label=\"阅读重点\"><a href=\"#headers\">1. 地址与请求头</a><a href=\"#ids\">2. ID 怎么传</a><a href=\"#time\">3. 时间怎么处理</a><a href=\"#results\">4. 结果怎么确认</a><a href=\"#boundaries\">5. 实现与验收怎么区分</a></nav><header class=\"guide-card guide-intro\"><span class=\"guide-kicker\">按 Android 实现整理 · 2026-10-23</span><h1>公共接口约定</h1><p class=\"guide-lead\">统一请求头、身份、ID 和错误处理；每个业务仍按自己的响应与写入契约校验。</p><p class=\"guide-scope\">统一调用约定及当前 Android 兼容行为；不能代替后端正式契约或各环境的部署验收。</p></header><section class=\"guide-section\" id=\"headers\"><h2><span class=\"guide-section-number\">1</span>地址与请求头</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>根地址</strong><p>路径相对所选环境，当前联调根路径包含 /admin；拼接一次，不能把 /app 或 /admin 重复加上。</p></li><li><strong>业务认证</strong><p>业务请求使用当前会话的 Bearer Token；OAuth、注册等专用客户端按各自约定处理，不一刀切替换认证头。</p></li><li><strong>时区</strong><p>统一发送 X-TimeZone，例如 Asia/Shanghai、America/New_York。每次请求读取系统 IANA 地区时区，不发送 UTC+8 或旧的 App-TimeZone。</p></li><li><strong>当前回退</strong><p>Android 对 UTC、GMT、Etc/* 等非地区格式回退 Asia/Shanghai；这是当前服务端适配规则。</p></li><li><strong>特殊客户端</strong><p>发码用 App-Client-Id，注册 / 密码接口用 X-Client-Id，不能全局改成同一个头。头像读取走匿名客户端，不向外部图片地址带 Token。</p></li><li><strong>语言</strong><p>公共业务客户端携带 lang（如 en-us / zh-cn）；AI POST / SSE 使用同一条消息的语言快照，独立图片客户端不携带业务认证或语言头。</p></li></ul></div></section><section class=\"guide-section\" id=\"ids\"><h2><span class=\"guide-section-number\">2</span>ID 怎么传</h2><div class=\"guide-section-body\"><div class=\"guide-table-scroll\" tabindex=\"0\" aria-label=\"字段说明表，可横向滚动\"><table><thead><tr><th>字段 / 区域</th><th>来源 / 内容</th><th>处理规则</th></tr></thead><tbody><tr><td>设备</td><td>deviceId</td><td>当作设备标识字符串保留，不按数值变换。</td></tr><tr><td>对象</td><td>type + 数字 ID</td><td>PERSON:101 是客户端组合标识；接口路径中的 personId / petId 只取对应数字 ID。</td></tr><tr><td>关联</td><td>bindingId</td><td>绑定记录 ID 用于解绑，不能拿 deviceId 或对象 ID 替代。</td></tr><tr><td>数值精度</td><td>服务端 Long / 数字字符串</td><td>按接口 DTO 区分，用 Int64 或无损字符串处理；不要先转 Double，也不要把所有服务器字段一律改成字符串。</td></tr></tbody></table></div></div></section><section class=\"guide-section\" id=\"time\"><h2><span class=\"guide-section-number\">3</span>时间怎么处理</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>设备实时位置</strong><p>latestLocation.dateTime 当前接受 12–13 位毫秒数或数字字符串，展示按手机时区；不能默认为秒或任意 ISO 文本。</p></li><li><strong>资料生日</strong><p>birthDate 是 YYYY-MM-DD 的日历日期，不是时间戳，不做时区偏移。</p></li><li><strong>健康 / 告警</strong><p>分析请求 date 当前按 UTC 日期，小时桶和 timeMillis 按手机时区显示；业务时段划分仍存在服务端问题。</p></li><li><strong>未知字段</strong><p>新增时间字段先确认类型、单位、时区和清空语义，不从 X-TimeZone 推定所有返回值都已转换为本地时间。</p></li></ul></div></section><section class=\"guide-section\" id=\"results\"><h2><span class=\"guide-section-number\">4</span>结果怎么确认</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>读取</strong><p>先判 HTTP，再检查业务 code / ok，最后按接口校验 data。空列表、null 与缺字段不能统一解释为失败或成功。</p></li><li><strong>写入</strong><p>先确认业务响应，再按业务回读；超时 / 取消不等于服务器没执行，不自动重放创建、绑定或下发指令。</p></li><li><strong>重试</strong><p>只读请求可按业务规则重试；明确无权限不保留受限旧数据。一个模块的 404 降级规则不能套用所有接口。</p></li><li><strong>身份隔离</strong><p>业务应绑定请求的环境、账号及资源，收到响应时核对上下文；切账号、环境或设备后，丢弃不匹配的旧结果。</p></li><li><strong>配置与设备效果</strong><p>POST 属性回显只算受理，必须独立 GET 比较完整组；设备 ACK、独立读回、真实声音和新 GPS 分开记录，HID 中继不能替代蜂窝直连验收。</p></li></ul></div></section><section class=\"guide-section\" id=\"boundaries\"><h2><span class=\"guide-section-number\">5</span>实现与验收怎么区分</h2><div class=\"guide-section-body\"><ul class=\"guide-rules\"><li><strong>代码依据</strong><p>说明里的流程来自当前客户端实现；原型操作仍只改本地演示数据。</p></li><li><strong>接口范围</strong><p>原 37 项 OpenAPI 快照保持 10-10 的原始来源；其接入状态按 10-23 代码复核。健康分析 4 项与新增分享 8 项按客户端声明单列，不伪造新服务器快照。</p></li><li><strong>验证范围</strong><p>已有报告的环境、账号、设备和异常分支分别标注。本轮整理文档不新增服务器验收结论。</p></li></ul></div></section><footer class=\"guide-footnote\">实现基线：Android a8ae598<br>TimeZoneHeaderInterceptor.kt / SystemTimeZoneProvider.kt / OAuthSessionManager / 各业务 Repository<br>原型使用演示数据；本轮未新增后端业务验收。</footer></main><script>// 原型和生成的离线 HTML 共用图表阅读器；不加载网络资源。\n(() => {\n  const dialog = document.createElement(\"dialog\");\n  dialog.className = \"guide-dialog\";\n  dialog.setAttribute(\"aria-labelledby\", \"guide-diagram-title\");\n  dialog.innerHTML = `<div class=\"guide-dialog-toolbar\"><strong id=\"guide-diagram-title\">图表</strong><div><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"out\" aria-label=\"缩小图表\">−</button><output aria-live=\"polite\">100%</output><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"in\" aria-label=\"放大图表\">＋</button><button class=\"guide-button\" type=\"button\" data-guide-zoom=\"fit\">适合窗口</button><button class=\"guide-button\" type=\"button\" data-guide-close>关闭</button></div></div><div class=\"guide-dialog-scroll\"><img alt=\"\"></div>`;\n  document.body.append(dialog);\n  const img = dialog.querySelector(\"img\");\n  const viewport = dialog.querySelector(\".guide-dialog-scroll\");\n  const output = dialog.querySelector(\"output\");\n  let baseWidth = 0;\n  let zoom = 1;\n  function applyZoom() {\n    img.style.width = `${Math.round(baseWidth * zoom)}px`;\n    output.textContent = `${Math.round(zoom * 100)}%`;\n  }\n  function fit() {\n    if (!img.naturalWidth) return;\n    const ratio = Math.min(1, (viewport.clientWidth - 40) / img.naturalWidth, (viewport.clientHeight - 40) / img.naturalHeight);\n    baseWidth = Math.max(1, img.naturalWidth * ratio);\n    zoom = 1;\n    applyZoom();\n    viewport.scrollTo(0, 0);\n  }\n  img.addEventListener(\"load\", fit);\n  document.addEventListener(\"click\", event => {\n    const trigger = event.target.closest(\"[data-guide-image], [data-guide-figure]\");\n    if (trigger) {\n      dialog.querySelector(\"strong\").textContent = trigger.dataset.guideTitle;\n      img.alt = trigger.dataset.guideTitle;\n      img.removeAttribute(\"style\");\n      dialog.showModal();\n      img.src = trigger.dataset.guideImage || trigger.closest(\"figure\").querySelector(\"img\").src;\n      if (img.complete) fit();\n    }\n    if (event.target.closest(\"[data-guide-print]\")) window.print();\n  });\n  dialog.addEventListener(\"click\", event => {\n    if (event.target.closest(\"[data-guide-close]\")) dialog.close();\n    const button = event.target.closest(\"[data-guide-zoom]\");\n    if (!button) return;\n    if (button.dataset.guideZoom === \"fit\") fit();\n    else {\n      zoom = Math.max(0.5, Math.min(4, zoom + (button.dataset.guideZoom === \"in\" ? 0.25 : -0.25)));\n      applyZoom();\n    }\n  });\n  window.addEventListener(\"resize\", () => { if (dialog.open) fit(); });\n})();\n</script></body></html>\n"};
